package com.artflow.studio.core.render

import com.artflow.studio.core.pixels.PixelBuffer
import com.artflow.studio.domain.model.layer.BlendMode
import com.artflow.studio.domain.model.layer.Layer
import com.artflow.studio.domain.model.layer.LayerBlendContract
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

/** Independent stored pixels and rational byte fixtures, never generated by the production blend helper. */
class NativeLayerBlendTest {
    @Test
    fun nativeArchivePixelsKeepZeroAndVerySmallDestinationAlpha() {
        val base = intArrayOf(0, 0x01000000, 0x04004040)
        val source = IntArray(base.size) { 0xFE151633.toInt() }
        assertArrayEquals(base, render(base, source))
        assertArrayEquals(source, render(base, source, native = false))
    }

    @Test
    fun independentPartialAndOpaquePixelsDistinguishNativeAndStandardDarken() {
        // Premultiplied source bytes (20,60,30,85); base bytes are
        // (0,0,0,0), (100,40,120,170), (210,90,150,255), (10,70,30,85).
        // Exact rational min(B, sourceOver) gives these straight, nearest-byte outputs.
        assertArrayEquals(
            intArrayOf(0, 0xAA823CA5.toInt(), 0xFFA05A82.toInt(), 0x551ED25A),
            render(BASE, SOURCE),
        )
        // Captured independently from the unchanged published v4 renderer as well.
        assertArrayEquals(
            intArrayOf(0x553CB45A, 0xC66F4D8D.toInt(), 0xFFA05A82.toInt(), 0x8E2AC05A.toInt()),
            render(BASE, SOURCE, native = false),
        )
    }

    @Test
    fun maskCoverageAndLayerOpacityRetainTheExistingByteMaskQuantization() {
        val base = IntArray(4) { 0xAA963CB4.toInt() }
        val source = IntArray(4) { 0x553CB45A }
        // Coverage0,1/5,3/5,1 maps source alpha85 to0,17,51,85 exactly;
        // layer opacity1/2 then applies to that source before the recovered minimum.
        val mask = intArrayOf(0xFF000000.toInt(), 0xFF333333.toInt(), 0xFF999999.toInt(), -1)
        assertArrayEquals(
            intArrayOf(0xAA963CB4.toInt(), 0xAA943CB3.toInt(), 0xAA903CB0.toInt(), 0xAA8C3CAD.toInt()),
            render(base, source, opacity = 0.5f, mask = mask),
        )
    }

    @Test
    fun disablingTheMaskRestoresTheUnmaskedNativeResult() {
        assertArrayEquals(
            intArrayOf(0, 0xAA823CA5.toInt(), 0xFFA05A82.toInt(), 0x551ED25A),
            render(BASE, SOURCE, mask = IntArray(4) { 0xFF000000.toInt() }, maskEnabled = false),
        )
    }

    @Test
    fun clippingUsesArtFlowsExistingOpaqueBaseThenRestoredAlphaContract() {
        val expected = intArrayOf(0, 0xAA783C96.toInt(), 0xFFA05A82.toInt(), 0x551EC85A)
        assertArrayEquals(expected, render(BASE, SOURCE, clipped = true))
        assertArrayEquals(expected, render(BASE, SOURCE, native = false, clipped = true))
        // This verifies the app's established clipping behavior. It does not infer host
        // group/hidden-layer routing in the native application from a shader flag's name.
    }

    @Test
    fun clippingWithMaskAndOpacityDoesNotChangeTheBaseCoverage() {
        assertArrayEquals(
            intArrayOf(0xAA8D3CAB.toInt()),
            render(
                intArrayOf(0xAA963CB4.toInt()),
                intArrayOf(0x553CB45A),
                opacity = 0.5f,
                mask = intArrayOf(0xFF999999.toInt()),
                clipped = true,
            ),
        )
    }

    @Test
    fun zeroSourceAndZeroOpacityLeaveTheExistingArtworkUntouched() {
        assertArrayEquals(BASE, render(BASE, IntArray(4)))
        assertArrayEquals(BASE, render(BASE, SOURCE, opacity = 0f))
        assertArrayEquals(BASE, render(BASE, SOURCE, visible = false))
    }

    @Test
    fun nativeDarkenPreservesEveryDestinationAlphaByte() {
        val base = IntArray(256) { alpha -> (alpha shl 24) or 0x7090B0 }
        val output = render(base, IntArray(256) { 0xA0602040.toInt() })
        for (alpha in 0..255) assertEquals(alpha, output[alpha] ushr 24)
    }

    private fun render(
        base: IntArray,
        source: IntArray,
        native: Boolean = true,
        opacity: Float = 1f,
        mask: IntArray? = null,
        maskEnabled: Boolean = true,
        clipped: Boolean = false,
        visible: Boolean = true,
    ): IntArray {
        val top =
            Layer(
                2,
                "Darken",
                1,
                isVisible = visible,
                opacity = opacity,
                blendMode = BlendMode.DARKEN,
                isClippingMask = clipped,
                maskEnabled = maskEnabled,
                blendContract = if (native) LayerBlendContract.PROCREATE_DARKEN_19 else LayerBlendContract.STANDARD,
            )
        val layers =
            listOf(
                Compositor.LayerInput(Layer(1, "Base", 0), PixelBuffer(base.size, 1, base.copyOf())),
                Compositor.LayerInput(top, PixelBuffer(source.size, 1, source.copyOf()), mask = mask?.let { PixelBuffer(it.size, 1, it) }),
            )
        return Compositor().composite(layers, base.size, 1).pixels
    }

    private companion object {
        val BASE = intArrayOf(0, 0xAA963CB4.toInt(), 0xFFD25A96.toInt(), 0x551ED25A)
        val SOURCE = IntArray(4) { 0x553CB45A }
    }
}
